import { requireJsonObject } from '../middleware/json-body.ts';
import { parseIdempotencyKey } from '../utils/idempotency.ts';
import { parsePositivePaise } from '../utils/money.ts';
import type { Router } from '../utils/router.ts';
import type { RefundService } from './refund-service.ts';

export interface RefundRouteDeps {
  refunds: RefundService;
}

export function registerRefundRoutes(router: Router, deps: RefundRouteDeps): void {
  router.post('/api/orders/:orderId/refund', async (request) => {
    const body = requireJsonObject(request.body);
    const amount = parsePositivePaise(body.amount);
    const idempotencyKey = parseIdempotencyKey(body.idempotencyKey);
    const result = await deps.refunds.refund({
      orderId: request.params.orderId!,
      amount,
      idempotencyKey,
    });
    return { status: 201, body: result };
  });
}

import { AppError } from '../utils/errors.ts';
import { fingerprintOf, type IdempotencyStore } from '../utils/idempotency.ts';
import { withRetry } from '../utils/retry.ts';
import { isRetryableProviderError, ProviderError, type PaymentProvider } from '../integrations/payment-provider.ts';
import type { OrderRepository } from '../orders/order-repository.ts';
import { refundableAmountOf, toOrderView, type OrderView } from '../orders/order.ts';
import type { Transaction, TransactionLedger } from '../payments/transaction-ledger.ts';
import type { Paise } from '../utils/money.ts';

export interface RefundServiceDeps {
  orders: OrderRepository;
  provider: PaymentProvider;
  idempotency: IdempotencyStore;
  ledger: TransactionLedger;
  clock: () => Date;
}

export interface RefundInput {
  orderId: string;
  amount: Paise;
  idempotencyKey: string;
}

export interface Refund {
  id: string;
  orderId: string;
  amount: Paise;
  status: 'succeeded';
  providerRefundId: string;
  idempotencyKey: string;
  createdAt: string;
}

export interface RefundResult {
  refund: Refund;
  order: OrderView;
}

/**
 * Refunds part or all of a paid order.
 *
 * Contract & ADRs:
 *   - ADR-001: integer paise
 *   - ADR-002: payment provider refund
 *   - ADR-003: idempotency with refund scope
 *   - ADR-004: standard error envelope
 *   - ADR-005: refund accounting (paid/partially_refunded status, running total, refundable amount check)
 */
export class RefundService {
  private readonly deps: RefundServiceDeps;

  constructor(deps: RefundServiceDeps) {
    this.deps = deps;
  }

  async refund(input: RefundInput): Promise<RefundResult> {
    const { orders, provider, idempotency, ledger, clock } = this.deps;
    const scope = `refund:${input.orderId}`;

    return idempotency.run(scope, input.idempotencyKey, fingerprintOf({ orderId: input.orderId, amount: input.amount }), async () => {
      const order = orders.get(input.orderId);

      if (order.status !== 'paid' && order.status !== 'partially_refunded') {
        throw new AppError('ORDER_NOT_REFUNDABLE', `Order ${order.id} has not been paid`, { orderId: order.id });
      }

      const refundable = refundableAmountOf(order);
      if (input.amount > refundable) {
        throw new AppError('REFUND_EXCEEDS_REFUNDABLE', `Refund amount ${input.amount} exceeds refundable amount ${refundable}`, {
          orderId: order.id,
          amount: input.amount,
          refundableAmount: refundable,
        });
      }

      if (!order.chargeId) {
        throw new AppError('ORDER_NOT_REFUNDABLE', `Order ${order.id} has no charge id`, { orderId: order.id });
      }

      const providerRefund = await withRetry(
        () =>
          provider.refund({
            chargeId: order.chargeId!,
            amount: input.amount,
            reference: order.id,
            idempotencyKey: input.idempotencyKey,
          }),
        { attempts: 3, isRetryable: isRetryableProviderError },
      ).catch((error: unknown) => {
        throw refundProviderFailure(error, order.id);
      });

      const now = clock().toISOString();
      const newRefundedAmount = order.refundedAmount + input.amount;
      const newStatus = newRefundedAmount === order.amount ? 'refunded' : 'partially_refunded';

      const saved = orders.save({
        ...order,
        status: newStatus,
        refundedAmount: newRefundedAmount,
        updatedAt: now,
      });

      const transaction = ledger.record({
        orderId: order.id,
        type: 'refund',
        amount: providerRefund.amount,
        provider: provider.name,
        providerReference: providerRefund.providerRefundId,
        idempotencyKey: input.idempotencyKey,
        createdAt: now,
      });

      const refund: Refund = {
        id: transaction.id,
        orderId: order.id,
        amount: providerRefund.amount,
        status: 'succeeded',
        providerRefundId: providerRefund.providerRefundId,
        idempotencyKey: input.idempotencyKey,
        createdAt: now,
      };

      return { refund, order: toOrderView(saved) };
    });
  }
}

export function refundProviderFailure(error: unknown, orderId: string): AppError {
  if (error instanceof ProviderError) {
    return new AppError('PAYMENT_PROVIDER_ERROR', 'The payment provider could not process the refund request', {
      orderId,
      providerCode: error.code,
    });
  }
  return new AppError('INTERNAL_ERROR', 'An unexpected error occurred');
}
